package kz.zani.mobile
import org.json.JSONObject
import org.junit.Test
import org.junit.Assert.*
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import kz.zani.mobile.core.*
import kz.zani.mobile.data.*
import kz.zani.mobile.ui.*

@OptIn(ExperimentalCoroutinesApi::class) class LeadReadTest {
    private fun raw()=javaClass.classLoader!!.getResourceAsStream("fixtures/lead-read.json")!!.bufferedReader().use {it.readText()}
    private fun repository()=APILeadReadRepository(ReadTransport {FixtureLeadReadTransport.response(raw(),it)})
    @Test fun exactMobileLeadProjectionScopeAndManualQueryContract()=runTest {
        val fixture=JSONObject(raw());val cases=fixture.getJSONArray("cases")
        for(i in 0 until cases.length()){val c=cases.getJSONObject(i);val valid=runCatching {if(c.getString("kind")=="page")LeadReadJSON.page(c.getJSONObject("payload").toString()).validFor(101)else LeadReadJSON.detail(c.getJSONObject("payload").toString()).validFor(101,3701)}.getOrDefault(false);assertEquals(c.getString("name"),c.getBoolean("valid"),valid)}
        val calls=mutableListOf<ReadRequest>();val api=APILeadReadRepository(ReadTransport {calls+=it;FixtureLeadReadTransport.response(raw(),it)});val page=api.leads(101,"\u001c ");val profile=api.lead(101,3701)
        assertEquals(listOf(ReadRequest("/api/mobile/v1/leads/",mapOf("business" to "101","limit" to "50","search" to "")),ReadRequest("/api/mobile/v1/leads/3701/",mapOf("business" to "101"))),calls);assertEquals(50,page.items.size);assertEquals(54,page.total);assertEquals(3701,page.items.first().id);assertEquals(1701,profile.lead.client_id);assertTrue(profile.message.length>profile.lead.message.length);assertEquals(listOf(3753),api.leads(101,"после окна50").items.map {it.id});assertEquals(404,FixtureLeadReadTransport.response(raw(),ReadRequest("/api/mobile/v1/leads/3755/",mapOf("business" to "101"))).status)
        for(status in listOf(403,404,500)){val denied=APILeadReadRepository(ReadTransport {ReadResponse(status,"")});val failure=runCatching {denied.leads(101,"")}.exceptionOrNull() as ReadException;assertEquals(when(status){403->ReadProblem.DENIED;404->ReadProblem.NOT_FOUND;else->ReadProblem.UNAVAILABLE},failure.problem)}
    }
    @Test fun actualModelManualWindowIndependentProfileAndLocalQualifiedUse()=runTest {
        val a=InboxConversationFilesContext(101,901,1,1);val b=InboxConversationFilesContext(202,951,2,1);val m=LeadReferenceModel(repository());m.bind(a);m.show();assertFalse(m.state.loaded);val input=m.input;m.update("e",input);m.update("e\u0301",input);assertEquals("e\u0301",m.state.query);m.clear(m.control);val old=m.control;m.search(old);assertEquals(50,m.state.items.size);assertTrue(m.state.partial);assertNull(m.state.choice);m.open(3701,old);assertNull(m.state.selectedID);m.open(3701,m.control);assertTrue(m.state.canUse);assertNull(m.state.choice);m.use(m.control);assertEquals(1701,m.state.choice!!.detail.lead.client_id);val stale=m.control;m.clearChoice(stale);m.use(stale);assertNull(m.state.choice);m.back(m.control);assertEquals(50,m.state.items.size);assertNull(m.state.detail);m.update("  после окна50\t",m.input);m.search(m.control);assertEquals(listOf(3753),m.state.items.map {it.id});m.open(3753,m.control);m.use(m.control);assertEquals("  после окна50\t",m.state.choice!!.rawQuery);m.hide();assertNull(m.state.choice);assertEquals("  после окна50\t",m.state.query);m.show();m.bind(b);m.show();assertEquals("",m.state.query);assertNull(m.state.choice)
        val files=InboxConversationFilesModel(APIInboxConversationFilesRepository(FixtureInboxConversationFilesTransport.fromJSON(javaClass.classLoader!!.getResourceAsStream("fixtures/inbox-conversation-files.json")!!.bufferedReader().use {it.readText()})),leads=repository());files.bind(a);assertTrue(files.open(files.control));val child=files.leadReference!!;assertTrue(child.state.presented);child.update("raw local",child.input);files.load(files.control);assertEquals("raw local",child.state.query);assertTrue(child.state.presented);files.items.firstOrNull()?.let {files.select(it,files.control);assertFalse(child.state.presented);files.back(files.control);assertTrue(child.state.presented);assertEquals("raw local",child.state.query)};files.bind(b);assertFalse(child.state.presented);assertEquals("",child.state.query)
        val s=LeadReadSession();s.bind(a);s.show();val ticket=s.beginList(s.control)!!;assertNull(s.beginList(s.control));s.bind(b);s.show();s.update("B raw",s.input);val current=s.control;assertFalse(s.accept(repository().leads(101,""),ticket));assertEquals(current,s.control);assertEquals("B raw",s.state.query);s.bind(a);s.show();assertFalse(s.accept(repository().leads(101,""),ticket));assertTrue(s.state.items.isEmpty())
    }
    private class Held:LeadReadRepository {val lists=mutableListOf<CompletableDeferred<LeadReadPage>>();val profiles=mutableListOf<CompletableDeferred<LeadReadDetail>>();override suspend fun leads(business:Int,search:String)=withContext(NonCancellable){CompletableDeferred<LeadReadPage>().also {lists+=it}.await()};override suspend fun lead(business:Int,id:Int)=withContext(NonCancellable){CompletableDeferred<LeadReadDetail>().also {profiles+=it}.await()}}
    @Test fun lateIgnoredCancellationBackDeniedAndBusinessABA()=runTest {
        val a=InboxConversationFilesContext(101,901,1,1);val b=InboxConversationFilesContext(202,951,2,1);val repo=repository();val page=repo.leads(101,"");val profile=repo.lead(101,3701);val held=Held();val m=LeadReferenceModel(held);m.bind(a);m.show();val pending=launch {m.search(m.control)};runCurrent();assertEquals(1,held.lists.size);m.bind(b);m.show();m.update("B raw",m.input);val current=m.control;held.lists[0].complete(page);pending.join();assertEquals(current,m.control);assertEquals("B raw",m.state.query);assertTrue(m.state.items.isEmpty());m.bind(a);m.show();val again=launch {m.search(m.control)};runCurrent();held.lists[1].complete(page);again.join();val first=launch {m.open(3701,m.control)};runCurrent();m.back(m.control);val back=m.control;held.profiles[0].complete(profile);first.join();assertEquals(back,m.control);assertNull(m.state.detail);val cancelled=launch {m.open(3701,m.control)};runCurrent();cancelled.cancel();held.profiles[1].complete(profile);cancelled.join();assertFalse(m.state.loading);assertNull(m.state.detail);assertNull(m.state.choice)
        val denied=LeadReferenceModel(object:LeadReadRepository {override suspend fun leads(business:Int,search:String)=page;override suspend fun lead(business:Int,id:Int):LeadReadDetail=throw ReadException(ReadProblem.DENIED)});denied.bind(a);denied.show();denied.search(denied.control);denied.open(3701,denied.control);assertEquals(ReadProblem.DENIED,denied.state.problem);denied.use(denied.control);assertNull(denied.state.choice);denied.back(denied.control);assertEquals(50,denied.state.items.size)
    }
}
